import { styled, View } from '@tamagui/web';
import type { ReactNode } from 'react';

import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { prependClassName } from '../../helpers/prependClassName';
import type { DivAttributes } from '../../types/ElementAttributes';

export type ModalFooterProps = DivAttributes & {
	children?: ReactNode;
	/** Spreads the actions apart instead of packing them at the end, for a footer with content on its start side. */
	justify?: 'end' | 'space-between';
};

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const footerFrame = {
	display: 'flex',
	flexDirection: 'row',
	alignItems: 'center',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	render: 'div',
	margin: 'var(--rcx-modal-container-margin, 1.5rem)',
} as const;

const footerJustifications = {
	'end': {
		justifyContent: 'end',
	},
	'space-between': {
		justifyContent: 'space-between',
	},
} as const;

// end of generated

// Declared where they render: zero-runtime only erases a `styled()` whose every use is in its own module
const FooterFrame = styled(View, {
	...footerFrame,
	variants: {
		justify: footerJustifications,
	},
});

const ModalFooter = (props: ModalFooterProps) => {
	const { justify = 'end' } = props;

	return (
		<FooterFrame
			justify={justify}
			className={prependClassName(props.className, `rcx-box rcx-box--full rcx-modal__footer rcx-modal__footer--justify-${justify}`)}
			render={<div {...ariaAndDataAttributes(props)} ref={props.ref} id={props.id} title={props.title} />}
		>
			{props.children}
		</FooterFrame>
	);
};

export default ModalFooter;
